export const QUP_STRINGS = { tr, en };
export function makeText(lang = 'tr', overrides) {
    const s = { ...QUP_STRINGS[lang], ...overrides };
    return (key, vars) => s[key].replace(/\{(\w+)\}/g, (_, k) => String(vars?.[k] ?? ''));
}
export function errorKey(code) {
    const k = `err.${code}`;
    return k in tr ? k : 'err.generic';
}
